import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Element-wise addition (reuse) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Custom transposed 2D convolution wrapper ----------
custom_conv_source = """
torch::Tensor custom_conv2d_cuda(torch::Tensor x, int out_channels,
                                 int kernel_size_h, int kernel_size_w,
                                 int stride_h=1, int stride_w=1,
                                 int padding_h=0, int padding_w=0,
                                 int dilation_h=1, int dilation_w=1,
                                 bool bias=False) {
    // Use the standard PyTorch transposed convolution via torch::conv_transpose2d.
    auto out = torch::conv_transpose2d(x, out_channels,
                                       kernel_size=(kernel_size_h, kernel_size_w),
                                       stride=(stride_h, stride_w),
                                       padding=(padding_h, padding_w),
                                       dilation=(dilation_h, dilation_w),
                                       groups=1, bias=bias);
    return out;
}
"""

custom_conv_cpp_source = "torch::Tensor custom_conv2d_cuda(torch::Tensor x, int out_channels, int kernel_size_h, int kernel_size_w, int stride_h=1, int stride_w=1, int padding_h=0, int padding_w=0, int dilation_h=1, int dilation_w=1, bool bias=False);"

custom_conv = load_inline(
    name="custom_conv2d_cuda",
    cpp_sources=custom_conv_cpp_source,
    cuda_sources=custom_conv_source,
    functions=["custom_conv2d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), output_padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups
        self.bias = bias

        # Keep the original conv_transpose2d for compatibility but we will use custom_conv2d_cuda in forward.
        self.conv_transpose2d = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride,
                                                   padding=padding, output_padding=output_padding,
                                                   dilation=dilation, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 2D convolution using a custom CUDA implementation.
        """
        return self.custom_conv2d_cuda(x, self.out_channels,
                                         self.kernel_size[0], self.kernel_size[1],
                                         self.stride[0], self.stride[1],
                                         self.padding[0], self.padding[1],
                                         self.dilation[0], self.dilation[1],
                                         self.bias)
